xpath.script:
(function () {
    try {
        var p = JSON.parse(localStorage.getItem('fusion_theme_pro.prefs') || '{}');
        var h = document.documentElement;
        var ok = function (v) { return typeof v === 'string' && /^[a-z]+$/.test(v); };
        if (ok(p.accent)) { h.setAttribute('data-fx-accent', p.accent); }
        if (ok(p.density)) { h.setAttribute('data-fx-density', p.density); }
        if (ok(p.corners)) { h.setAttribute('data-fx-corners', p.corners); }
        var mode = p.mode;
        if (mode === 'auto') {
            mode = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
        }
        if (mode === 'dark' || mode === 'light') {
            h.setAttribute('data-fx-mode', mode);
            h.style.colorScheme = mode;
        }
    } catch (e) { /* storage unavailable: defaults apply */ }
})();
